#!/usr/bin/env python3
"""Generate tests/mod/fixtures.ts from tests/mod/fixtures/*.json.

A hooks-module test can neither read files nor import JSON, so the contract
plans are inlined into a TypeScript module. tests/test_mod_fixtures.py fails
when the committed file differs from what this script renders.
"""

import json
import sys
from pathlib import Path

MOD_TESTS = Path(__file__).resolve().parent.parent / "tests" / "mod"

HEADER = """\
// GENERATED by scripts/gen_mod_fixtures.py from tests/mod/fixtures/*.json (the
// exact stdout of scripts/drive-take.sh). A hooks-module test cannot read files
// or import JSON, so the plans are inlined here, one JSON string per fixture,
// with @ROOT@ for the session root. Do not edit; tests/test_mod_fixtures.py
// fails when this file and the JSON disagree.
export const FIXTURES = {
"""


def main() -> None:
    """Rewrite fixtures.ts next to the fixtures directory."""
    text = render(MOD_TESTS / "fixtures")
    (MOD_TESTS / "fixtures.ts").write_text(text, encoding="utf-8")
    sys.stdout.write("wrote tests/mod/fixtures.ts\n")


def render(fixtures_dir: Path) -> str:
    """Return the text of fixtures.ts for fixtures_dir's JSON files, by name."""
    rows = []
    for path in sorted(fixtures_dir.glob("*.json")):
        body = path.read_text(encoding="utf-8").rstrip("\n")
        key = json.dumps(path.stem)
        rows.append(f"  {key}: {json.dumps(body, ensure_ascii=False)},\n")
    return HEADER + "".join(rows) + "}\n"


if __name__ == "__main__":
    main()
